const takePendingEvents = `-- name: TakePendingEvents :many
WITH picked AS (
  SELECT e.id FROM ai_inbox_events e
  WHERE e.store_id = $1 AND e.inbox_id = $2
    AND e.status = 'pending' AND e.not_before <= $3
    AND e.attempts < $4::int
  ORDER BY e.created_at, e.id
  LIMIT 50
  FOR NO KEY UPDATE SKIP LOCKED
),
updated AS (
  UPDATE ai_inbox_events
  SET status = 'running', attempts = attempts + 1, lease_token = $5, last_error = NULL
  WHERE id IN (SELECT id FROM picked)
  RETURNING tenant_id, store_id, id, inbox_id, kind, source_key, subject_kind, subject_id, payload, status, attempts, not_before, last_error, lease_token, session_id, created_at, done_at
)
SELECT tenant_id, store_id, id, inbox_id, kind, source_key, subject_kind, subject_id, payload, status, attempts, not_before, last_error, lease_token, session_id, created_at, done_at FROM updated ORDER BY created_at, id
`

type TakePendingEventsParams struct {
	StoreID     uuid.UUID
	InboxID     uuid.UUID
	Now         pgtype.Timestamptz
	MaxAttempts int32
	LeaseToken  *uuid.UUID
}

type TakePendingEventsRow struct {
	TenantID    uuid.UUID
	StoreID     uuid.UUID
	ID          uuid.UUID
	InboxID     uuid.UUID
	Kind        string
	SourceKey   string
	SubjectKind *string
	SubjectID   *uuid.UUID
	Payload     []byte
	Status      string
	Attempts    int32
	NotBefore   pgtype.Timestamptz
	LastError   *string
	LeaseToken  *uuid.UUID
	SessionID   *uuid.UUID
	CreatedAt   pgtype.Timestamptz
	DoneAt      pgtype.Timestamptz
}

func (q *Queries) TakePendingEvents(ctx context.Context, arg TakePendingEventsParams) ([]TakePendingEventsRow, error) {
	rows, err := q.db.Query(ctx, takePendingEvents,
		arg.StoreID,
		arg.InboxID,
		arg.Now,
		arg.MaxAttempts,
		arg.LeaseToken,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TakePendingEventsRow
	for rows.Next() {
		var i TakePendingEventsRow
		if err := rows.Scan(
			&i.TenantID,
			&i.StoreID,
			&i.ID,
			&i.InboxID,
			&i.Kind,
			&i.SourceKey,
			&i.SubjectKind,
			&i.SubjectID,
			&i.Payload,
			&i.Status,
			&i.Attempts,
			&i.NotBefore,
			&i.LastError,
			&i.LeaseToken,
			&i.SessionID,
			&i.CreatedAt,
			&i.DoneAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

